document.head.insertAdjacentHTML("beforeend", "<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/400.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/700.css\">");
document.body.insertAdjacentHTML("afterbegin", "<div id=\"intro\">\n<div class=\"pv\"><video controls playsinline preload=\"none\" poster=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/pv-poster.webp\"><source src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/pv.webm\" type='video/webm; codecs=\"av01.0.08M.10, opus\"'><source src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/pv.mp4\" type=\"video/mp4\"></video></div>\n<div class=\"seam\"></div>\n<div class=\"main\">\n<p class=\"lead\">毕业季，你和女友洛槿、她的同学祝凛，跟着瑞典闺蜜莉妮娅飞往瑞典中部的哈尔辛兰。山谷深处的哈尔加村，今年夏至要办九十年一次的盛宴，白夜不落，人人换上亲手织的白色亚麻衣裙，绕着五月柱起舞。接下来每一步怎么走，由你来定。</p>\n<h2>怎么玩</h2>\n<div class=\"row\" style=\"--c:#E8B923\"><span class=\"t\">时间</span><span>从抵达日开始，到第 9 天夜里结束。每天分上午、下午、傍晚、夜里四个时段，每一回合最多向前推进一个时段。</span></div>\n<div class=\"row\" style=\"--c:#D8452F\"><span class=\"t\">地点</span><span>抵达日在机场、路上、村外草地；入村以后可以在村里 17 处地点之间走动，每一处都有自己的场景图。</span></div>\n<div class=\"row\" style=\"--c:#E48AA3\"><span class=\"t\">节目</span><span>盛宴每天都有排好的节目，按时间一件件到来，重要的大场面会配一张大图。</span></div>\n<div class=\"row\" style=\"--c:#27407A\"><span class=\"t\">行动</span><span>想做什么、想说什么，直接写在输入框里就行，一句话、一段话都可以。</span></div>\n<h2>每条回复末尾的功能栏</h2>\n<div class=\"row\" style=\"--c:#E8B923\"><span class=\"t\">日程</span><span>仲夏节日程页：今天的民俗小科普，以及四个时段的安排，还没到的时段只显示「尚未到来」。</span></div>\n<div class=\"row\" style=\"--c:#3F6FB5\"><span class=\"t\">地图</span><span>哈尔加地图页：村子的俯瞰图，点圆点看场景图与介绍，你所在的地点会被标出来。</span></div>\n<div class=\"row\" style=\"--c:#E48AA3\"><span class=\"t\">立绘</span><span>女主立绘页：五位女主的介绍、四问四答和立绘，点下方缩略图切换大图。</span></div>\n<h2>开始之前</h2>\n<div class=\"row\" style=\"--c:#5E7E44\"><span class=\"t\">运行</span><span>需要安装酒馆助手与提示词模板。</span></div>\n<div class=\"row\" style=\"--c:#5E7E44\"><span class=\"t\">变量</span><span>回复结尾的变量更新由系统自动维护；弹出「变量发生错误」的提示时，重新生成本楼即可。</span></div>\n<div class=\"go\"><button id=\"go\">进入开场</button><span class=\"hint\">也可以点消息框的右箭头，切换到下一条开场白</span></div>\n<p class=\"credit\">制卡 ssd（类脑 @buyssdcom），保留一切权利</p>\n</div>\n</div>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{overflow:hidden}\nbody{font-family:\"Noto Serif SC\",\"Source Han Serif SC\",\"Songti SC\",\"STSong\",\"SimSun\",serif;font-size:14px;line-height:1.7;color:#27302A;background:transparent}\n#intro{background:#FBFAF6;border:1px solid #E2DFD3;border-radius:12px;overflow:hidden}\n.pv{aspect-ratio:16/9;background:#000}\n.pv video{display:block;width:100%;height:100%}\n.seam{height:4px;background:linear-gradient(90deg,#5E7E44,#E8B923,#D8452F,#E48AA3,#8A6CB4,#3F6FB5)}\n.main{padding:16px 18px 18px}\n.lead{font-size:14px;line-height:1.95;text-align:justify}\nh2{margin:18px 0 2px;font-size:15px;letter-spacing:.14em}\n.row{display:grid;grid-template-columns:3.4em 1fr;gap:10px;margin-top:8px;padding:9px 12px;border-left:3px solid var(--c);border-radius:0 8px 8px 0;background:#FFFFFF;font-size:13px;line-height:1.75}\n.row .t{font-weight:700;color:var(--c)}\n.go{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:20px}\n#go{padding:9px 44px;border:0;border-radius:8px;background:#5E7E44;font:inherit;font-size:16px;letter-spacing:.3em;text-indent:.3em;color:#fff;cursor:pointer;transition:filter .15s}\n#go:hover{filter:brightness(1.1)}\n.hint{font-size:12px;color:#6B7166}\n.credit{margin-top:14px;font-size:11.5px;letter-spacing:.06em;text-align:center;color:#6B7166}\n@media (max-width:520px){.main{padding:14px 12px 16px}.lead{font-size:13px;line-height:1.9}.row{font-size:12.5px}}\n</style>");
document.getElementById('go').addEventListener('click', () => triggerSlash('/swipe'));
